mapper.select:
SELECT EXISTS(
SELECT 1 FROM follow
WHERE follower_id = #{followerId}
AND following_id = #{followingId}
)

mapper.delete:
DELETE FROM follow
WHERE follower_id = #{followerId}
AND following_id = #{followingId}

mapper.select:
SELECT
f.id AS followId,
m.id AS memberId,
m.nickname AS nickname,
m.profile_image AS profileImage,
EXISTS(
SELECT 1 FROM follow me
WHERE me.follower_id = #{loginMemberId}
AND me.following_id = m.id
) AS isFollowing
FROM follow f
JOIN member m ON m.id = f.follower_id
WHERE f.following_id = #{memberId}

    AND f.id < #{lastFollowId}

ORDER BY f.id DESC
LIMIT #{limit}

